export const completeCatalogueCardIds = completeCatalogueCards
  .map((cardDefinition) => cardDefinition.id)
  .sort();

function card(
  id: string,
  name: string,
  category: ExpectedCatalogueCard['category'],
  affinity: ExpectedCatalogueCard['affinity'],
  rarity: ExpectedCatalogueCard['rarity'],
  hp: number | null,
  power: number | null,
  starterEligible = false,
  rewardEligible = false,
  cpuEligible = false,
): ExpectedCatalogueCard {
  return {
    affinity,
    category,
    cpuEligible,
    evolvesFromDefinitionId: null,
    hp,
    id,
    name,
    power,
    rarity,
    rewardEligible,
    starterEligible,
  };
}

function evolution(
  id: string,
  name: string,
  affinity: Exclude<ExpectedCatalogueCard['affinity'], null>,
  rarity: 'epic' | 'legendary',
  hp: number,
  power: number,
  evolvesFromDefinitionId: string,
): ExpectedCatalogueCard {
  return {
    ...card(id, name, 'creature', affinity, rarity, hp, power),
    evolvesFromDefinitionId,
  };
}
